#include "AStarPathfinder.h"
#include "NavGraphBuilder.h"
#include "Algo/Reverse.h"
TArray<FVector> UAStarPathfinder::FindPath(UNavGraph*G,const FVector&S,const FVector&T)const{TArray<FVector> Out;if(!G||G->Nodes.IsEmpty())return Out;const int32 SI=G->FindNearestNode(S),GI=G->FindNearestNode(T);if(SI<0||GI<0)return Out;const int32 N=G->Nodes.Num();TArray<float> GS,FS;TArray<int32> Prev;GS.Init(TNumericLimits<float>::Max(),N);FS.Init(TNumericLimits<float>::Max(),N);Prev.Init(INDEX_NONE,N);auto H=[&](int32 I){return FVector::Distance(G->Nodes[I].Position,G->Nodes[GI].Position);};GS[SI]=0;FS[SI]=H(SI);TArray<int32> Open{SI};TSet<int32> Closed;int32 Iter=0;while(!Open.IsEmpty()&&Iter++<FMath::Max(1,MaxIterations)){int32 BestI=0;for(int32 I=1;I<Open.Num();++I)if(FS[Open[I]]<FS[Open[BestI]])BestI=I;const int32 Cur=Open[BestI];Open.RemoveAtSwap(BestI);if(Cur==GI){int32 P=Cur;while(P!=INDEX_NONE){Out.Add(G->Nodes[P].Position);P=Prev[P];}Algo::Reverse(Out);return Out;}Closed.Add(Cur);for(int32 V:G->Nodes[Cur].Neighbors){if(!G->Nodes.IsValidIndex(V)||Closed.Contains(V))continue;const float Tent=GS[Cur]+FVector::Distance(G->Nodes[Cur].Position,G->Nodes[V].Position)*FMath::Max(.001f,G->Nodes[V].BaseCost);if(Tent<GS[V]){Prev[V]=Cur;GS[V]=Tent;FS[V]=Tent+H(V);if(!Open.Contains(V))Open.Add(V);}}}return Out;}
